import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    for i in range(V):
        line_parts = []
        try:
            while True:
                val = next(iterator)
                if val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
                    line_parts.append(int(val))
                else:
                    break
        except StopIteration:
            pass

        for neighbor in line_parts:
            if 0 <= neighbor < V:
                adj[i].append(neighbor)

    tin = [-1] * V
    low = [-1] * V
    parent = [-1] * V
    ap = [False] * V
    timer = 0

    def dfs(u):
        nonlocal timer
        children = 0
        tin[u] = low[u] = timer
        timer += 1

        for v in adj[u]:
            if v == u:
                continue
            if tin[v] == -1:
                parent[v] = u
                children += 1
                dfs(v)
                low[u] = min(low[u], low[v])
                if parent[u] != -1 and low[v] >= tin[u]:
                    ap[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], tin[v])

        if parent[u] == -1 and children > 1:
            ap[u] = True

    for i in range(V):
        if tin[i] == -1:
            dfs(i)

    result = []
    for i in range(V):
        if ap[i]:
            result.append(i)

    if not result:
        print("-1")
    else:
        print(" ".join(map(str, sorted(result))))

if __name__ == "__main__":
    solve()
